style.css:
@-moz-document domain("pinterest.com") {
/* Change all text to #CD1414 */
    body, body * {
        color: #CD1414 !important;
    }

    /* Change the background color to #000000 */
    body {
        background-color: #000000 !important;
    }

    /* Change the header background to #000000 */
    header, header * {
        background-color: #000000 !important;
        color: #CD1414 !important; /* Make sure text inside the header is visible */
    }

    /* Change the highlight/selection color */
    ::selection {
        background-color: #501212 !important;
        color: #FFFFFF !important; /* Ensure selected text is readable */
    }

    /* Change the color of links on hover (for better visibility on dark background) */
    a:hover, a:focus {
        color: #501212 !important;
    }

    /* Optional: Customize the color of buttons (if Pinterest uses buttons in some sections) */
    button, .button, .btn {
        background-color: #501212 !important;
        color: #FFFFFF !important; /* Ensure text on buttons is visible */
    }
}
